  guideSlug: "60-30-10-color-rule-explained",
  guideTitle: "The 60-30-10 Color Rule Explained for a Real Living Room",
  metaTitle: "The 60-30-10 Color Rule Explained",
  metaDescription: "What 60-30-10 means in a real living room: where the 60, 30 and 10 percent live in walls, upholstery and accents, how to count them and when to break the rule.",
  heroImage: "/images/articles/color603010-paint-swatches-wall.webp",
